function startMusic() {
  if (music.on || !isLive()) return;
  for (let he of MUSIC_LAYERS) if (!buffers.has(he + '#0')) return;
  let te = webAudioCtx.currentTime + 0.08;
  for (let he of MUSIC_LAYERS) {
    let pe = gainNode(0),
      ge = webAudioCtx.createBufferSource();
    ge.buffer = buffers.get(he + '#0'), ge.loop = !0, ge.connect(pe), pe.connect(buses.music), ge.start(te), music.layers[he] = {
      g: pe,
      s: ge,
      c: 0
    };
  }
  music.on = !0, music.t0 = te;
}

/**
 * 爆炸后耳鸣：三个近 4kHz 正弦缓慢衰减，短暂提示听力受损并强化爆炸冲击。
 * @module-ref src/audio/library.js
 */
function synthEarRing(sr) {
  let e = allocSamples(sr, 2.4);
  for (let t = 0; t < e.length; t++) {
    let n = t / sr;
    e[t] = (Math.sin(TAU * 3150 * n) + 0.7 * Math.sin(TAU * 4013 * n + 1) + 0.35 * Math.sin(TAU * 5310 * n + 2)) * (1 - Math.exp(-n / 0.12)) * Math.exp(-n / 0.55);
  }
  return e;
}
/**
 * 金属弹着：非谐和（1.58 倍频程堆叠）模态共振簇，刻意不平整才像真实钢板。
 * @module-ref src/audio/library.js
 */

/**
 * mulberry32 变体的 32 位种子随机数发生器；音效烘焙用固定种子，保证同一配方每次生成的波形逐采样一致（可复现、可跨 session 缓存）。
 * @module-ref src/audio/synthesis.js
 */
function ao(seed) {
  let e = seed >>> 0;
  return () => {
    e |= 0, e = e + 1831565813 | 0;
    let t = Math.imul(e ^ e >>> 15, 1 | e);
    return t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t, ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
