function createShapeFromPoints(points, holes) {
  let t = new THREE.Shape();
  if (points.forEach((n, s) => s ? t.lineTo(n[0], n[1]) : t.moveTo(n[0], n[1])), t.closePath(), holes) for (let n of holes) t.holes.push(new THREE.Path(n.map(s => new THREE.Vector2(s[0], s[1]))));
  return t;
}
