/**
 * 生成海面网格的一维坐标序列：步长按比例几何递增并设上限，近处顶点密远处疏，在顶点预算内保住近处浪形
 * @module-ref src/world/ground/ground.js
 */
function buildSeaGridSteps(start, end, step, growth, maxStep) {
  let o = [start],
    r = start,
    a = step;
  for (; r < end - 0.001;) r = Math.min(end, r + a), o.push(r), a = Math.min(maxStep, a * growth);
  return o;
}
/**
