 * @module-ref src/world/ground/water.js
 */

function emitSparkBurst(ee, B, P, V, Y, L, Z, J, oe, fe, le, R) {
  for (let I = 0; I < P; I++) {
    randomDirectionAround(B, L, FX_SCRATCH_VEC_D);
    let se = randRange(V, Y) * (0.35 + 0.65 * fxRandom());
    emitStreak(ee.x, ee.y, ee.z, FX_SCRATCH_VEC_D.x * se, FX_SCRATCH_VEC_D.y * se, FX_SCRATCH_VEC_D.z * se, randRange(Z, J), randRange(0.01, 0.02), oe * randRange(0.6, 1.2), fe * randRange(0.6, 1.2), le, R);
  }
}

