function mapVertices(geometry, fn) {
  let t = geometry.attributes.position,
    n = new THREE.Vector3();
  for (let s = 0; s < t.count; s++) n.fromBufferAttribute(t, s), fn(n, s), t.setXYZ(s, n.x, n.y, n.z);
  return geometry;
}
